package set_parameter

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/generated/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "set_parameter"
	command.Identifiers = []string{"set-parameter"}
	command.Category = "Server System"
	command.Help = "Rewrite one entry of a route's parameters"
	command.LongDescription = "Rewrites one entry of the route's parameters in place and runs build. It is add-parameter applied to a declaration that already exists: the keys given are written over the ones there, --clear takes one off, and the result goes through the same constructor."
	command.Examples = []string{"set-parameter page --route list-users --type number --default 1", "set-parameter token --route admin --font header --clear trigger"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route (identifier or package name) that declares the parameter",
			Examples:    []string{"set-parameter page --route list-users --type number"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--route"},
		},
		{
			Id:          "rename",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the key the parameter takes on",
			Examples:    []string{"set-parameter page --route list-users --rename p"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--rename"},
		},
		{
			Id:          "type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the new value type: string, integer, number, boolean, datetime, string-array or integer-array",
			Examples:    []string{"set-parameter page --route list-users --type integer"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--type"},
		},
		{
			Id:          "font",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "where the value is read from, in order: query, header or cookie (repeatable; replaces the whole list)",
			Examples:    []string{"set-parameter token --route admin --font header --font cookie"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--font"},
		},
		{
			Id:          "required",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "answer 400 when no font brings the value",
			Examples:    []string{"set-parameter q --route search --required"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--required"},
		},
		{
			Id:          "default",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the new literal bound when no font brings the value",
			Examples:    []string{"set-parameter page --route list-users --default 1"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--default"},
		},
		{
			Id:          "trigger",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the new value the parameter has to match for the route to run",
			Examples:    []string{"set-parameter authorization --route admin --trigger Bearer"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger"},
		},
		{
			Id:          "trigger-type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the new comparison: equal, prefix, text-prefix, suffix or regex — or starts-with, ends-with, exact, matches",
			Examples:    []string{"set-parameter authorization --route admin --trigger-type prefix"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-type"},
		},
		{
			Id:          "trigger-negate",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "invert the trigger (take it off with --clear trigger-negate)",
			Examples:    []string{"set-parameter authorization --route public --trigger-negate"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-negate"},
		},
		{
			Id:          "trigger-ignore-case",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "compare the trigger without regard to case (take it off with --clear trigger-ignore-case)",
			Examples:    []string{"set-parameter authorization --route admin --trigger-ignore-case"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-ignore-case"},
		},
		{
			Id:          "description",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the new help text",
			Examples:    []string{"set-parameter page --route list-users --description 'the page to read'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--description"},
		},
		{
			Id:          "example",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "an extra usage example (repeatable)",
			Examples:    []string{"set-parameter page --route list-users --example '?page=3'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--example"},
		},
		{
			Id:          "clear",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a key to take off: description, examples, default, required, trigger, trigger-negate or trigger-ignore-case (repeatable)",
			Examples:    []string{"set-parameter page --route list-users --clear default"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--clear"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"set-parameter page --route list-users --type number --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the key of the parameter to rewrite",
			Examples:    []string{"set-parameter page --route list-users --type number"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
